                </li>
              ))}
            </Box>
          )}
        </Box>

        <Box
          component="section"
          aria-label={`Map of ${results.length} homes in ${SITE.city}`}
          sx={{
            display: { xs: view === "map" ? "block" : "none", md: "block" },
            height: { xs: "calc(100dvh - 280px)", md: "calc(100dvh - 220px)" },
