  return daysSinceListed(home.listed) <= 7;
}

export function formatListed(listed: string): string {
  const d = daysSinceListed(listed);
  if (d <= 0) return "Listed today";
  if (d === 1) return "Listed yesterday";
  return `Listed ${d} days ago`;
}

