import { Home, SITE, bedsLabel, formatPrice, formatPriceShort } from "@/lib/data";

interface MapViewProps {
  homes: Home[];
  hoveredId: string | null;
  selectedId: string | null;
  onHover: (id: string | null) => void;
  onSelect: (id: string | null) => void;
